/* src/kernel/font.css */
@font-face { font-family:"Noto Serif SC"; src:url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/notoserifsc/notoserifsc.woff2") format("woff2"); font-style:normal; font-weight:200 900; font-display:swap; }

/* src/tokens.css */
:root {
  --moon-ink: #223d67;
  --moon-paper: #b7c9ec;
  --moon-white: #eef4ff;
  --moon-mid: #8faadc;
  --moon-soft: #cadbfa;
  --moon-focus: #375eac;
  --moon-disabled: #536f9c;
  --moon-error: #53367e;
  --theme-surface: var(--moon-paper);
  --theme-surface-muted: var(--moon-soft);
  --theme-surface-disabled: #a5bbe3;
  --theme-text-primary: var(--moon-ink);
  --theme-text-secondary: #385881;
  --theme-text-disabled: var(--moon-disabled);
  --theme-border: #6686b7;
  --theme-focus-ring: var(--moon-focus);
  --theme-opacity-disabled: 1;
  --theme-shadow: none;
  --theme-code-inline-surface: #a1b9e5;
  --theme-code-block-surface: #1d365c;
  --theme-code-text: #e0edff;
  --theme-code-muted: #a9c8fa;
  --theme-code-accent: #b9acf5;
  --theme-code-selection: #476cb5;
  --moon-font: "Noto Serif SC", "Songti SC", SimSun, serif;
  --moon-avatar: 2.7rem;
  --moon-gap: .65rem;
  --moon-avatar-slot: calc(var(--moon-avatar) + var(--moon-gap));
  --st-theme-mobile-reading-width: 100%;
  --st-theme-mobile-reading-padding: .35em;
}

/* src/kernel/scrollbars.css */
/*
 * v7 固定全局无滚动条外观内核。
 * 只隐藏浏览器滚动条外观，不修改 overflow、touch-action、pointer-events，
 * 不隐藏滚动容器、跳转键、功能按钮或 input[type="range"]。
 * 全局 * 是本项目唯一允许的无边界选择器例外，不得增加其他声明。
 */
::-webkit-scrollbar {
    display: none !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

/* src/chat-layout.css */
body {
  color: var(--moon-ink);
  background-color: var(--moon-ink);
  font-family: var(--moon-font);
  text-shadow: none;
  --topBarBlockSize: 4.2rem;
}
#chat {
  background-color: var(--moon-paper);
  background-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/a86f929889fc48f67bcd50427940f0e4e78a6e64/assets/%E6%9C%88%E7%9B%B8%E4%B9%8B%E9%97%B4/moon-print.png"), linear-gradient(90deg, var(--moon-ink) 31%, var(--moon-paper) 31%);
  background-size: 100% 100%, 100% 100%;
  background-repeat: no-repeat;
  background-position: center;
  background-attachment: scroll;
  border: 0;
  padding: 0 0 1rem;
}
#chat .mes[is_system="false"] {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  box-sizing: border-box;
  padding: 1.6rem 1.25rem 1.5rem;
  gap: .65rem;
  border: 0;
  background: transparent;
  min-width: 0;
}
#chat .mes[is_user="true"][is_system="false"] {
  width: 31%;
  margin-inline: 0 auto;
  color: var(--moon-white);
  --SmartThemeBodyColor: var(--moon-white);
  --SmartThemeEmColor: var(--moon-soft);
  --SmartThemeQuoteColor: var(--moon-white);
}
#chat .mes[is_user="false"][is_system="false"] {
  width: 69%;
  margin-inline: auto 0;
  color: var(--moon-ink);
}
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  flex: 0 0 auto;
  align-self: flex-start;
  margin: 0;
  width: auto;
  min-width: 0;
}
#chat .mes[is_system="false"] > .mes_block {
  width: 100%;
  inline-size: 100%;
  min-width: 0;
  padding: 0;
  overflow: visible;
}
#chat .mes .avatar, #chat .mes .avatar img {
  width: var(--moon-avatar);
  height: var(--moon-avatar);
  border-radius: 50%;
  object-fit: cover;
  box-sizing: border-box;
  box-shadow: none;
  border: 1px solid var(--moon-mid);
}
#chat .mes .ch_name {
  gap: .4em;
  flex-wrap: wrap;
  font-family: var(--moon-font);
  margin-bottom: .7em;
}
#chat .name_text {
  font-size: 1.1em;
  font-weight: 700;
  color: inherit;
}
#chat .timestamp, #chat .mesIDDisplay, #chat .mes_timer, #chat .tokenCounterDisplay {
  color: inherit;
  font-size: .72em;
  opacity: 1;
  text-shadow: none;
}
#chat .mes[is_system="true"], #chat .mes.selected {
  color: var(--theme-text-primary) !important;
  background-color: var(--theme-surface) !important;
  border-color: var(--theme-border) !important;
  opacity: 1 !important;
  filter: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
#chat .mes.selected {
  outline: 2px dashed var(--moon-focus);
  outline-offset: -2px;
}
@media (max-width: 1050px) {
#chat {
  background-image: none;
  background-color: var(--moon-paper);
}
}
@media (max-width: 1050px) {
#chat .mes[is_user="true"][is_system="false"] {
  width: 100%;
  background-color: var(--moon-ink);
  padding: 1rem;
}
}
@media (max-width: 1050px) {
#chat .mes[is_user="false"][is_system="false"] {
  width: 100%;
  background-color: var(--moon-paper);
  padding: 1rem;
}
}
@media (max-width: 700px) {
#chat .mes[is_system="false"] {
  flex-direction: column;
  align-items: stretch;
}
}
@media (max-width: 700px) {
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  align-self: center;
  margin-inline: auto;
}
}
@media (max-width: 700px) {
#chat .mes[is_system="false"] > .mes_block {
  inline-size: 100%;
  min-inline-size: 0;
}
}
@media (max-width: 700px) {
#chat .mes[is_system="false"] > .mes_block > .mes_text {
  inline-size: min(100%, var(--st-theme-mobile-reading-width));
  max-inline-size: 100%;
  margin-inline: auto !important;
  padding-inline: var(--st-theme-mobile-reading-padding) !important;
  box-sizing: border-box;
}
}

/* src/full-text.css */
#chat .mes_text {
  font-family: var(--moon-font);
  font-weight: 500;
  font-size: 1em;
  line-height: 1.85;
  color: inherit;
  padding: 0;
  margin: 0;
  overflow-wrap: anywhere;
}
#chat .mes_text p {
  margin: 0 0 1.15em;
}
#chat .mes[is_user="false"][is_system="false"] .mes_text > p:first-child:not(:has(code, img, video, iframe, a, strong, em))::first-letter {
  font-size: 2.4em;
  font-weight: 700;
  line-height: 1.2;
  color: var(--moon-ink);
  background-color: var(--moon-white);
  border-radius: 50%;
  padding: .06em .18em;
  margin-inline-end: .08em;
}
#chat .mes_text :is(h1,h2,h3,h4) {
  font-family: var(--moon-font);
  color: inherit;
  font-weight: 700;
  line-height: 1.45;
  margin-block: 1em .5em;
}
#chat .mes_text :is(strong,b) {
  font-weight: 700;
  color: inherit;
}
#chat .mes_text :is(em,i:not([class*="fa-"])) {
  font-style: normal;
  color: inherit;
  text-decoration: underline;
  text-decoration-color: var(--moon-mid);
  text-underline-offset: .2em;
}
#chat .mes_text blockquote {
  background-color: var(--moon-ink);
  color: var(--moon-white);
  border: 1px dashed var(--moon-mid);
  padding: .85em 1em;
  margin: 1.2em 0;
  border-radius: .15em;
  text-shadow: none;
}
#chat .mes_text blockquote :is(p,q,em,strong) {
  color: var(--moon-white);
}
#chat .mes_text q {
  color: var(--moon-white);
  background-color: var(--moon-ink);
  padding: .08em .3em;
  box-decoration-break: clone;
}
#chat .mes_text :is(ul,ol) {
  padding-inline-start: 1.5em;
}
#chat .mes_text a {
  color: inherit;
  text-decoration: underline;
  text-underline-offset: .2em;
}
#chat .mes_text :is(img,video,iframe) {
  max-width: 100%;
}
#chat .mes_text table {
  display: block;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
}
#chat .mes_text :is(th,td) {
  border: 1px solid var(--theme-border);
  padding: .45em .65em;
}

