/* src/windows/input.css */
#send_form {
  background-color: var(--moon-ink);
  border: 1px solid var(--moon-mid);
  border-radius: 2rem;
  padding: .35rem;
  min-height: 3.3rem;
  box-sizing: border-box;
  box-shadow: none;
}
#send_form #nonQRFormItems {
  align-items: center;
  gap: .3rem;
  min-width: 0;
}
#send_form :is(#leftSendForm,#rightSendForm) {
  flex: 0 0 auto;
  flex-wrap: nowrap;
  align-items: center;
  gap: .15rem;
  padding: 0;
}
#send_form #send_textarea {
  flex: 1 1 0%;
  min-width: 0;
  width: 0;
  min-height: 2.7rem;
  height: auto;
  max-height: 35dvh;
  padding: .65rem .9rem;
  box-sizing: border-box;
  border: 1px solid var(--moon-mid);
  border-radius: 1.6rem;
  background-color: var(--moon-paper);
  color: var(--moon-ink);
  font-family: var(--moon-font);
  font-size: 1em;
  line-height: 1.45;
  box-shadow: none;
  text-shadow: none;
}
#send_form #send_textarea::placeholder {
  color: var(--theme-text-secondary);
  opacity: 1;
}
#send_form.no-connection #send_textarea {
  border-style: dashed;
  border-color: var(--moon-white);
}
#send_form #send_textarea:focus-visible {
  outline: 2px solid var(--moon-white);
  outline-offset: 1px;
}
#send_form :is(#options_button,#extensionsMenuButton,#send_but,#mes_stop,#mes_continue,#mes_impersonate,.stscript_btn) {
  width: 2.7rem;
  height: 2.7rem;
  min-width: 2.7rem;
  padding: .35rem;
  box-sizing: border-box;
  font-size: 1.5rem;
  color: var(--moon-white) !important;
  background-color: var(--moon-ink) !important;
  border: 1px solid var(--moon-mid);
  border-radius: 50%;
  opacity: 1 !important;
  filter: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
#send_form #options_button {
  color: var(--moon-white) !important;
  opacity: 1 !important;
  filter: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
#send_form #extensionsMenuButton {
  color: var(--moon-white) !important;
  opacity: 1 !important;
  filter: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
#send_form #send_but {
  color: var(--moon-white) !important;
  opacity: 1 !important;
  filter: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
#send_form #mes_stop {
