/* src/windows/mobile.css */
@media (max-width: 700px) {
body {
  --topBarBlockSize: 3.2rem;
  --moon-avatar: 2.3rem;
}
}
@media (max-width: 700px) {
#top-settings-holder .drawer-icon {
  font-size: 1.25rem;
  width: 2rem;
  height: 3rem;
  padding: .2rem 0;
  max-width: 100%;
}
}
@media (max-width: 700px) {
#top-settings-holder .drawer-icon::after {
  font-size: .5rem;
  letter-spacing: 0;
}
}
@media (max-width: 700px) {
#send_form {
  border-radius: 1.3rem;
  padding: .25rem;
  min-height: 2.8rem;
}
}
@media (max-width: 700px) {
#send_form :is(#options_button,#extensionsMenuButton,#send_but,#mes_stop,#mes_continue,#mes_impersonate,.stscript_btn) {
  width: 2.1rem;
  height: 2.1rem;
  min-width: 2.1rem;
  font-size: 1.15rem;
  padding: .2rem;
}
}
@media (max-width: 700px) {
#send_form #send_textarea {
  min-height: 2.3rem;
  padding: .5rem .6rem;
  font-size: .95em;
}
}
@media (max-width: 700px) {
:is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel).drawer-content {
  min-width: 0;
